const normalizar = (str) => (str || "").toString().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim().toLowerCase();
const rawWebhook = $('Webhook Busca').first()?.json || {};
const webhookBody = rawWebhook.body || rawWebhook;
let iaConfig = {};
try { const qwenStr = $('Qwen Ollama').first()?.json?.response; if (qwenStr) iaConfig = JSON.parse(qwenStr); } catch(e) {}
const reqSkills = Array.isArray(iaConfig.skills) && iaConfig.skills.length > 0 ? iaConfig.skills : (Array.isArray(webhookBody.skills) ? webhookBody.skills : []);
const reqDisp = Number(iaConfig.disponibilidade_minima ?? webhookBody.disponibilidade_minima ?? 50);
const reqSen = (iaConfig.senioridade ?? webhookBody.senioridade ?? "").toString();
const reqMeses = Number(iaConfig.tempo_alocacao_meses ?? webhookBody.tempo_alocacao_meses ?? 3);
const modoDisp = webhookBody.modo_disponibilidade || "faixa_ate";
const mapaMeses = { Jan:'01', Fev:'02', Mar:'03', Abr:'04', Mai:'05', Jun:'06', Jul:'07', Ago:'08', Set:'09', Out:'10', Nov:'11', Dez:'12' };
const agrupado = {};
for (const item of $input.all()) {
  const linha = item.json;
  if (!linha.colaborador) continue;
  const id = linha.id_colaborador;
  if (!agrupado[id]) {
    agrupado[id] = { id_colaborador: id, colaborador: linha.colaborador, senioridade: linha.senioridade || "Não informada", cargo: linha.cargo || "Não informado", skills: new Set(), demandas_atuais: new Map(), meses: {} };
  }
  if (linha.skill) agrupado[id].skills.add(linha.skill.trim());
  if (linha.demanda && linha.id_demanda) agrupado[id].demandas_atuais.set(linha.id_demanda, { id_demanda: linha.id_demanda, nome_demanda: linha.demanda });
  if (linha.ano && linha.mes && linha.id_alocacao) {
    const mesNum = mapaMeses[linha.mes] || '01';
    const periodo = `${linha.ano}-${mesNum}`;
    if (!agrupado[id].meses[periodo]) agrupado[id].meses[periodo] = { total_alocado: 0, alocacoes_vistas: new Set() };
    const chaveAlocacao = `${linha.id_alocacao}-${periodo}`;
    if (!agrupado[id].meses[periodo].alocacoes_vistas.has(chaveAlocacao)) {
      agrupado[id].meses[periodo].alocacoes_vistas.add(chaveAlocacao);
      agrupado[id].meses[periodo].total_alocado += Number(linha.percentual_na_demanda || 0);
    }
  }
}
const aprovados = [];
for (const id in agrupado) {
  const dev = agrupado[id];
  if (reqSen && normalizar(dev.senioridade) !== normalizar(reqSen)) continue;
  const skillsDev = Array.from(dev.skills);
  const skillsEncontradas = reqSkills.filter(req => skillsDev.some(s => normalizar(s) === normalizar(req)));
  if (reqSkills.length > 0 && skillsEncontradas.length === 0) continue;
  const periodosAvaliados = Object.keys(dev.meses).sort().slice(-reqMeses);
  let somaAlocado = 0;
  for (const p of periodosAvaliados) somaAlocado += Math.min(100, dev.meses[p].total_alocado);
  const alocadoMedio = periodosAvaliados.length > 0 ? Math.round(somaAlocado / periodosAvaliados.length) : 0;
  const livreMedio = Math.max(0, 100 - alocadoMedio);
  let aprovadoTempo = true;
  if (modoDisp === "estrito_0_a_x") aprovadoTempo = (livreMedio >= 0 && livreMedio <= reqDisp);
  else if (modoDisp === "minimo") aprovadoTempo = (livreMedio >= reqDisp);
  if (!aprovadoTempo) continue;
  const statusAlocacao = livreMedio >= reqDisp ? "Disponível para Alocação Direta" : `Requer Remanejamento (${livreMedio}% livre / meta ${reqDisp}%)`;
  aprovados.push({
    match_encontrado: true, origem: "SGD (Interno)", id_colaborador: dev.id_colaborador, colaborador: dev.colaborador, cargo: dev.cargo, senioridade: dev.senioridade, status_acao: statusAlocacao, skills_buscadas_atendidas: skillsEncontradas, qtd_skills_atendidas: skillsEncontradas.length, qtd_skills_pedidas: reqSkills.length, percentual_alocado_medio: alocadoMedio, disponibilidade_media: livreMedio, projetos_atuais: Array.from(dev.demandas_atuais.values()), score_ranking: reqSkills.length > 0 ? Math.round((skillsEncontradas.length / reqSkills.length) * 100) : 100
  });
}
aprovados.sort((a, b) => b.score_ranking - a.score_ranking || b.disponibilidade_media - a.disponibilidade_media);
if (aprovados.length === 0) return [{ json: { match_encontrado: false } }];
return aprovados.map(c => ({ json: c }));

const normalizar = (str) => (str || "").toString().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim().toLowerCase();
const rawWebhook = $('Webhook Busca').first()?.json || {};
const webhookBody = rawWebhook.body || rawWebhook;
let iaConfig = {};
try { const qwenStr = $('Qwen Ollama').first()?.json?.response; if (qwenStr) iaConfig = JSON.parse(qwenStr); } catch(e) {}
const reqSkills = Array.isArray(iaConfig.skills) && iaConfig.skills.length > 0 ? iaConfig.skills : (Array.isArray(webhookBody.skills) ? webhookBody.skills : []);
const reqDisp = Number(iaConfig.disponibilidade_minima ?? webhookBody.disponibilidade_minima ?? 50);
const reqSen = (iaConfig.senioridade ?? webhookBody.senioridade ?? "").toString();
const talentosAgrupados = {};
for (const item of $input.all()) {
  const linha = item.json;
  if (!linha.talento) continue;
  const id = linha.id_talento;
  if (!talentosAgrupados[id]) {
    talentosAgrupados[id] = { id_talento: id, colaborador: linha.talento, senioridade: linha.senioridade || "Não informada", cargo: linha.cargo || "Não informado", disponibilidade_media: Number(linha.disponibilidade ?? 100), skills: new Set() };
  }
  if (linha.skill) talentosAgrupados[id].skills.add(linha.skill.trim());
}
const aprovados = [];
for (const id in talentosAgrupados) {
  const cand = talentosAgrupados[id];
  if (reqSen && cand.senioridade !== "Não informada" && normalizar(cand.senioridade) !== normalizar(reqSen)) continue;
  if (cand.disponibilidade_media < reqDisp) continue;
  const skillsCand = Array.from(cand.skills);
  const skillsAtendidas = reqSkills.filter(req => skillsCand.some(s => normalizar(s) === normalizar(req)));
  if (reqSkills.length > 0 && skillsAtendidas.length === 0) continue;
  aprovados.push({
    match_encontrado: true, origem: "Banco de Talentos (Externo)", id_talento: cand.id_talento, colaborador: cand.colaborador, cargo: cand.cargo, senioridade: cand.senioridade, skills_buscadas_atendidas: skillsAtendidas, qtd_skills_atendidas: skillsAtendidas.length, qtd_skills_pedidas: reqSkills.length, disponibilidade_media: cand.disponibilidade_media, status_acao: "Disponível para Alocação Direta", score_ranking: reqSkills.length > 0 ? Math.round((skillsAtendidas.length / reqSkills.length) * 100) : 100
  });
}
aprovados.sort((a, b) => b.score_ranking - a.score_ranking || b.disponibilidade_media - a.disponibilidade_media);
if (aprovados.length === 0) return [{ json: { match_encontrado: false, mensagem: "Nenhum profissional encontrado." } }];
return aprovados.map(t => ({ json: t }));

const itens = $input.all().map(i => i.json);
const rawWebhook = $('Webhook Busca').first()?.json || {};
const webhookBody = rawWebhook.body || rawWebhook;
let iaConfig = {};
try { const qwenStr = $('Qwen Ollama').first()?.json?.response; if (qwenStr) iaConfig = JSON.parse(qwenStr); } catch(e) {}
const filtrosFinais = Object.keys(iaConfig).length > 0 ? iaConfig : webhookBody;
const encontrou = itens.length > 0 && itens[0].match_encontrado !== false;
const resposta = {
  resumo_busca: {
    status: encontrou ? "Sucesso" : "Sem resultados",
    origem_dados: encontrou ? itens[0].origem : "Nenhuma",
    total_encontrados: encontrou ? itens.length : 0,
    filtros_extraidos: filtrosFinais
  },
  ranking: encontrou ? itens.map((cand, idx) => ({
    posicao: `${idx + 1}º`,
    id: cand.id_colaborador || cand.id_talento,
    tipo_base: cand.id_colaborador ? "interno" : "externo",
    nome: cand.colaborador,
    cargo: cand.cargo,
    senioridade: cand.senioridade,
    aderencia_skills: `${cand.score_ranking}% (${cand.qtd_skills_atendidas}/${cand.qtd_skills_pedidas})`,
    skills_atendidas: cand.skills_buscadas_atendidas || [],
    alocacao_atual: `${cand.percentual_alocado_medio ?? 0}%`,
    tempo_livre: `${cand.disponibilidade_media}%`,
    status_acao: cand.status_acao || "Disponível para Contratação",
    projetos_atuais: cand.projetos_atuais || []
  })) : []
};
return [{ json: resposta }];

