WITH reduzir_antiga AS (
    UPDATE "InHire".planejamentos p SET porcentagem = {{ Number($json.body?.nova_porcentagem_demanda_antiga ?? 50) }} FROM "InHire".alocacoes a WHERE p.id_alocacao = a.id AND a.id_colaborador = {{ Number($json.body?.id_colaborador) }} AND a.id_demanda = {{ Number($json.body?.id_demanda_antiga ?? 0) }} AND p.ano = {{ Number($json.body?.ano ?? 2026) }} AND p.mes = '{{ ($json.body?.mes || "Nov").replace(/'/g, "''") }}' RETURNING p.id AS id_plan_antigo
), alocacao_existente AS (
    SELECT id FROM "InHire".alocacoes WHERE id_colaborador = {{ Number($json.body?.id_colaborador) }} AND id_demanda = {{ Number($json.body?.id_demanda_nova ?? 1) }} LIMIT 1
), nova_alocacao AS (
    INSERT INTO "InHire".alocacoes (id_colaborador, id_demanda, status, deletado) SELECT {{ Number($json.body?.id_colaborador) }}, {{ Number($json.body?.id_demanda_nova ?? 1) }}, true, false WHERE NOT EXISTS (SELECT 1 FROM alocacao_existente) RETURNING id
), alocacao_final AS (
    SELECT id FROM nova_alocacao UNION ALL SELECT id FROM alocacao_existente LIMIT 1
), atualiza_plan_novo AS (
    UPDATE "InHire".planejamentos p SET porcentagem = {{ Number($json.body?.porcentagem_nova_demanda ?? 50) }}, status = true, deletado = false FROM alocacao_final af WHERE p.id_alocacao = af.id AND p.ano = {{ Number($json.body?.ano ?? 2026) }} AND p.mes = '{{ ($json.body?.mes || "Nov").replace(/'/g, "''") }}' RETURNING p.id
), insere_plan_novo AS (
    INSERT INTO "InHire".planejamentos (id_alocacao, mes, ano, porcentagem, status, deletado) SELECT af.id, '{{ ($json.body?.mes || "Nov").replace(/'/g, "''") }}', {{ Number($json.body?.ano ?? 2026) }}, {{ Number($json.body?.porcentagem_nova_demanda ?? 50) }}, true, false FROM alocacao_final af WHERE NOT EXISTS (SELECT 1 FROM atualiza_plan_novo) RETURNING id
) SELECT {{ Number($json.body?.id_colaborador) }} AS id_colaborador;
